function addCaseTable(slide, title, subtitle, rows, acceptedCount) {
  addHeader(slide, title);
  slide.addText(subtitle, {x:0.75,y:0.85,w:12.0,h:0.35,fontSize:12,color:C.muted,italic:true});

  const x=0.8, y=1.3, w=11.9;
  const hHead=0.55, hRow=0.73;
  slide.addShape(pptx.ShapeType.rect,{x,y,w,h:hHead,fill:{color:'1E293B'},line:{color:'1E293B',pt:1}});
  const col=[1.8,2.0,8.1];
  slide.addText('Date',{x:x+0.08,y:y+0.15,w:col[0]-0.16,h:0.2,fontSize:12,bold:true,color:'FFFFFF',align:'center'});
  slide.addText('Outcome',{x:x+col[0]+0.08,y:y+0.15,w:col[1]-0.16,h:0.2,fontSize:12,bold:true,color:'FFFFFF',align:'center'});
  slide.addText('Rationale',{x:x+col[0]+col[1]+0.08,y:y+0.15,w:col[2]-0.16,h:0.2,fontSize:12,bold:true,color:'FFFFFF'});

  rows.forEach((r,i)=>{
    const yy = y+hHead+i*hRow;
    const bg = i%2===0 ? 'F8FAFC' : 'EEF2FF';
    slide.addShape(pptx.ShapeType.rect,{x,y:yy,w,h:hRow,fill:{color:bg},line:{color:'CBD5E1',pt:0.8}});
    slide.addShape(pptx.ShapeType.line,{x:x+col[0],y:yy,w:0,h:hRow,line:{color:'CBD5E1',pt:0.8}});
    slide.addShape(pptx.ShapeType.line,{x:x+col[0]+col[1],y:yy,w:0,h:hRow,line:{color:'CBD5E1',pt:0.8}});
    slide.addText(r.date,{x:x+0.08,y:yy+0.22,w:col[0]-0.16,h:0.2,fontSize:11,align:'center',color:C.textDark});
    slide.addText(r.outcome,{x:x+col[0]+0.08,y:yy+0.22,w:col[1]-0.16,h:0.2,fontSize:11,bold:true,align:'center',color:r.outcome==='Accepted'?C.accent:C.reject});
    slide.addText(r.why,{x:x+col[0]+col[1]+0.12,y:yy+0.14,w:col[2]-0.2,h:0.45,fontSize:11,color:C.textDark});
  });

  slide.addShape(pptx.ShapeType.roundRect,{x:0.8,y:6.35,w:4.2,h:0.6,rectRadius:0.08,fill:{color:'ECFDF5'},line:{color:'86EFAC',pt:1}});
  slide.addText(`Accepted ${acceptedCount} / 6 attempts`,{x:0.95,y:6.54,w:3.9,h:0.22,fontSize:12,bold:true,color:'166534'});
}

